//! The primitive polynomials and the initial direction numbers of the Sobol sequence, based on
//! those that Stephen Joe and Frances Kuo generated in the joe-kuo-6.10200 set. See
//! http://web.maths.unsw.edu.au/~fkuo/sobol/index.html.

pub const max_m = 17;

pub const Primitive = struct {
    /// The dimension number of the polynomial. Unused.
    dimension: u32,
    /// The degree of the polynomial.
    degree: u32,
    /// A binary word that represents the coefficients.
    a: u32,
    /// The m values.
    m: []const u32,
};

